WITH metrics AS (SELECT *, MAX(amount) OVER w_hist AS last7_max_amount, COUNT(amount) OVER w_hist AS last7_count_amount, MIN(amount) OVER w_hist AS last7_min_amount, AVG(amount) OVER (ORDER BY amount, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS amount_avg_6_prior FROM payments WINDOW w_hist AS (PARTITION BY method ORDER BY amount, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)) SELECT CASE WHEN amount >= 1330 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, order_id, PERCENTILE_APPROX(last7_count_amount, 0.95) AS last7_count_amount_p95, COUNT(CASE WHEN method = 'paypal' THEN 1 END) AS paypal_count, ROUND(AVG(last7_count_amount), 2) AS avg_last7_count_amount FROM metrics GROUP BY CASE WHEN amount >= 1330 THEN 'HIGH' ELSE 'LOW' END, order_id ORDER BY avg_last7_count_amount;
